def verify(witness):
    if set(witness.keys()) != {'N_max', 'r_list', 'sidon_max', 'note'}:
        raise ValueError('unexpected witness schema')
    Nmax = witness['N_max']
    rs = witness['r_list']
    K = witness['sidon_max']
    if Nmax != 8:
        raise ValueError('N_max must be 8')
    if sorted(rs) != [2, 3]:
        raise ValueError('r_list must be [2, 3]')
    if len(K) != 8:
        raise ValueError('sidon_max must have 8 entries')
    for k in K:
        if not (isinstance(k, int) and 1 <= k <= Nmax):
            raise ValueError('bad sidon_max entry')

    def is_sidon(A):
        s = []
        for i in range(len(A)):
            for j in range(i, len(A)):
                s.append(A[i] + A[j])
        return len(set(s)) == len(s)

    def subsets(N):
        out = []
        for mask in range(1 << N):
            A = []
            for i in range(N):
                if (mask >> i) & 1:
                    A.append(i + 1)
            out.append(A)
        return out

    # (1) Sidon sharpness on N<=8: exhaustive max compared to witness table.
    Kcomp = []
    for N in range(1, Nmax + 1):
        best = 0
        for A in subsets(N):
            if len(A) > best and is_sidon(A):
                best = len(A)
        Kcomp.append(best)
    if Kcomp != K:
        raise ValueError('sidon_max table mismatch')

    # (2) S_r floor on N<=8: exhaustive minimum of sum_{n=r}^{N} f_r(n)^2 over
    # all A subseteq {1..N} whose r-fold sumset covers [r,N]; invariants:
    # lower bound N-r+1, monotonicity in N; re-verify argmin independently.
    def sums_of(A, r, N):
        sums = {}
        combos = [[]]
        for _ in range(r):
            nxt = []
            for c in combos:
                start = c[-1] if c else 0
                for a in A:
                    if a >= start:
                        nxt.append(c + [a])
            combos = nxt
        for c in combos:
            s = 0
            for a in c:
                s += a
            if r <= s <= N:
                sums[s] = sums.get(s, 0) + 1
        return sums

    for r in rs:
        prev = None
        for N in range(r, Nmax + 1):
            best = None
            arg = None
            for A in subsets(N):
                sums = sums_of(A, r, N)
                ok = True
                for n in range(r, N + 1):
                    if n not in sums:
                        ok = False
                        break
                if not ok:
                    continue
                cost = 0
                for v in sums.values():
                    cost += v * v
                if best is None or cost < best:
                    best = cost
                    arg = A
            if best is None:
                raise ValueError('no covering set found (verifier bug)')
            if best < (N - r + 1):
                raise ValueError('square-sum below provable lower bound N-r+1')
            if prev is not None and best < prev:
                raise ValueError('non-monotone in N')
            sums = sums_of(arg, r, N)
            for n in range(r, N + 1):
                if n not in sums:
                    raise ValueError('argmin fails coverage')
            cost = 0
            for v in sums.values():
                cost += v * v
            if cost != best:
                raise ValueError('argmin cost mismatch')
            prev = best

    # (3) Invariant sanity on the Sidon table: nondecreasing in N.
    for i in range(1, 8):
        if K[i] < K[i - 1]:
            raise ValueError('sidon_max not nondecreasing')

    return True
